package com.bplus.share;
import android.app.*;import android.content.*;import android.net.Uri;import android.widget.*;import org.json.*;import java.io.*;
public final class Attachments{
 public static String state(Activity a,JSONObject m){String raw=m.optString("uri");if(raw.isEmpty())return "reference";try(android.content.res.AssetFileDescriptor f=a.getContentResolver().openAssetFileDescriptor(Uri.parse(raw),"r")){return f==null?"missing":"ok";}catch(SecurityException e){return "permission";}catch(FileNotFoundException e){return "missing";}catch(Exception e){return "provider";}}
 public static String explanation(Activity a,String state){return a.getString(state.equals("reference")?R.string.attach_no_reference:state.equals("permission")?R.string.attach_permission:state.equals("missing")?R.string.attach_missing:R.string.attach_provider);}
 public static void locate(Activity a,JSONObject m,int request){new AppDialog(a).setTitle(R.string.locate_file).setMessage(explanation(a,state(a,m))+"\n\n"+a.getString(R.string.locate_safe_note)).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.locate_file,(d,n)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);a.startActivityForResult(i,request);}).show();}
 public static boolean readable(Activity a,Uri uri){try(android.content.res.AssetFileDescriptor f=a.getContentResolver().openAssetFileDescriptor(uri,"r")){return f!=null;}catch(Exception e){return false;}}
 public static void folder(Activity a,JSONObject m){try{Uri u=FileCards.uri(m);if(u!=null&&android.provider.DocumentsContract.isDocumentUri(a,u)){String id=android.provider.DocumentsContract.getDocumentId(u);int slash=id.lastIndexOf('/');if(slash>id.indexOf(':')){Uri parent=android.provider.DocumentsContract.buildDocumentUri(u.getAuthority(),id.substring(0,slash));Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(parent,"vnd.android.document/directory").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(view);return;}}}catch(Exception ignored){}Toast.makeText(a,R.string.folder_fallback,Toast.LENGTH_LONG).show();try{Intent files=new Intent(android.app.DownloadManager.ACTION_VIEW_DOWNLOADS);a.startActivity(files);}catch(Exception e){Toast.makeText(a,R.string.no_file_app,Toast.LENGTH_LONG).show();}}
 public static void snapshot(){synchronized(Store.class){if(Store.get("schemaVersion","").equals("111"))return;try{JSONObject copy=new JSONObject();copy.put("peers",Store.peers());copy.put("library",new JSONArray(Store.get("library","[]")));JSONObject threads=new JSONObject();JSONArray peers=Store.peers();for(int i=0;i<peers.length();i++){String id=peers.getJSONObject(i).getString("id");threads.put(id,Store.thread(id));}copy.put("threads",threads);Store.set("pre111ReferenceSnapshot",copy.toString());Store.set("schemaVersion","111");}catch(Exception ignored){}}}
}
